        self.info = await self._c.update(self.id, schedule=schedule, run=run, retry=retry, secrets=secrets, vcpu=vcpu, memory_gb=memory_gb, disk_gb=disk_gb, image=image, user=user, volumes=volumes, max_cost=max_cost, idempotency_key=idempotency_key)
